const { chromium } = require('playwright');
const path = require('path');

(async () => {
  try {
    const browser = await chromium.launch({ args: ['--no-sandbox', '--disable-setuid-sandbox'] });
    const page = await browser.newPage({
      viewport: { width: 1682, height: 2378 }
    });

    // Load the local HTML file
    const fileUrl = 'file://' + path.resolve('/app/output/poster.html');
    await page.goto(fileUrl, { waitUntil: 'networkidle' });

    // Wait for the graphics to render (Infographic uses web fonts and canvas, wait a bit)
    await page.waitForTimeout(3000); 

    // Take screenshot
    await page.screenshot({ path: '/app/output/final_poster.png', fullPage: true });

    await browser.close();
    console.log("Screenshot saved to /app/output/final_poster.png");
  } catch (err) {
    console.error(err);
    process.exit(1);
  }
})();
